18→export type CheckboxProps = Omit<ComponentProps<'input'>, 'defaultChecked' | 'checked'> & {
19→  /** Whether this component should be unstyled. */
20→  unstyled?: undefined | boolean,
21→  
22→  /** The default state of the checkbox at initialization time. Default: undefined. */
