 28→export type CheckboxTriLabeledProps = CheckboxTriProps & {
 29→  label: React.ComponentProps<typeof Label>['label'],
 30→  labelProps?: undefined | React.ComponentProps<typeof Label>,
 31→};
 32→export const CheckboxTriLabeled = ({ label, labelProps, ...props }: CheckboxTriLabeledProps) =>
 33→  <Label position="inline-end" label={label} {...labelProps}><CheckboxTri {...props}/></Label>;
 34→
 35→/**
 36→ * A variant of checkbox that allows a third "indeterminate" state meaning neither checked nor unchecked. This can be
 37→ * useful for example for "select all" checkboxes, where the checkbox will be indeterminate if some (but not all) of
 38→ * the items are currently checked.
 39→ */
 40→export const CheckboxTri = Object.assign(
 41→  (props: CheckboxTriProps) => {
 42→    const {
 43→      unstyled = false,
 44→      defaultChecked,
 45→      checked,
 46→      ...propsRest
 47→    } = props;
 48→    
 49→    const checkboxRef = React.useRef<React.ComponentRef<typeof Checkbox>>(null);
 50→    
 51→    // Keep track of the `indeterminate` state of the checkbox. Needed so that we can rerender the component when
 52→    // `indeterminate` changes. There is no event that triggers when `indeterminate` is changed.
 53→    const [_internalIndeterminate, setInternalIndeterminate] = React.useState<undefined | boolean>(undefined);
 54→    
 55→    const handleChange = React.useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
 56→      props.onChange?.(event);
 57→      
 58→      // Force rerender of the component if the `indeterminate` state changed (but `checked` didn't)
 59→      setInternalIndeterminate(event.target.indeterminate);
 60→      
 61→      const checkedUpdated: CheckboxTriState = event.target.indeterminate ? 'indeterminate' : event.target.checked;
 62→      props.onUpdate?.(checkedUpdated);
 63→    }, [props.onChange, props.onUpdate]);
 64→    
 65→    // Sync `defaultChecked` with the checkbox
 66→    useEffectOnce(() => {
 67→      const checkbox = checkboxRef.current;
 68→      if (!checkbox) { return; }
 69→      checkbox.indeterminate = defaultChecked === 'indeterminate';
 70→      setInternalIndeterminate(checkbox.indeterminate);
 71→    });
 72→    
 73→    // Sync `checked` with the checkbox.
 74→    // Note: HTML checkbox elements support an intermediate state, but it can only be set through the DOM.
 75→    React.useEffect(() => {
 76→      const checkbox = checkboxRef.current;
 77→      if (!checkbox) { return; }
 78→      if (typeof checked === 'undefined') { return; } // Do not run this for uncontrolled components
 79→      
 80→      if (checked === 'indeterminate' && !checkbox.indeterminate) {
 81→        checkbox.indeterminate = true;
 82→        setInternalIndeterminate(true);
 83→      } else if (checked !== 'indeterminate' && checkbox.indeterminate) {
 84→        checkbox.indeterminate = false;
 85→        setInternalIndeterminate(false);
 86→      }
 87→    }, [checked]);
 88→    
 89→    // Note: use `true` if `indeterminate`, so that clicking on an indeterminate state goes to unchecked state
 90→    const defaultCheckedBoolean: undefined | boolean = defaultChecked === 'indeterminate' ? true : defaultChecked;
 91→    
 92→    const checkedBoolean = ((): undefined | boolean => {
 93→      // If the checkbox is uncontrolled, keep it uncontrolled
 94→      if (typeof checked === 'undefined') { return undefined; }
 95→      
 96→      // Note: this considers `indeterminate` to imply `checked=true`. This is so that if the user clicks on the checkbox
 97→      // while it is indeterminate, then the checkbox will change to unchecked.
 98→      // Note: in HTML, the `checked` and `indeterminate` states are separate, so you can have `checked=false` and
 99→      // `indeterminate=true`. If we want to support such a use case, we could consider adding a separate `indeterminate`
100→      // prop.
101→      return checked === 'indeterminate' ? true : checked;
102→    })();
103→    
104→    return (
105→      <Checkbox
106→        {...propsRest}
107→        ref={mergeRefs(checkboxRef, propsRest.ref)}
108→        defaultChecked={defaultCheckedBoolean}
109→        checked={checkedBoolean}
110→        onChange={handleChange}
111→      />
112→    );
113→  },
114→  {
115→    Labeled: CheckboxTriLabeled,
116→  },
117→);
