 5→import * as React from 'react';
 6→import { mergeRefs, useEffectOnce } from '../../../util/reactUtil.ts';
 7→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 8→
 9→import { Spinner } from '../../graphics/Spinner/Spinner.tsx';
10→import { ModalProvider, type ModalProviderProps } from '../../util/overlays/modal/ModalProvider.tsx';
11→
12→import cl from './SpinnerModal.module.scss';
13→
14→
15→export { cl as SpinnerModalClassNames };
16→
17→export type SpinnerModalProps = React.PropsWithChildren<ComponentProps<typeof Spinner> & {
18→  /** A reference to the modal, for imperative control. */
19→  modalRef?: undefined | React.Ref<React.ComponentRef<typeof ModalProvider>>,
20→  
21→  /** Any additional props to pass to the modal provider. */
22→  providerProps?: undefined | Omit<ModalProviderProps, 'children'>,
23→  
24→  /** Delay until the spinner is visible. Useful to prevent flashing for short actions. Default: 1 second. */
25→  delay?: undefined | number,
26→}>;
27→/**
28→ * A loading spinner displayed as modal.
29→ */
30→export const SpinnerModal = (props: SpinnerModalProps) => {
31→  const { modalRef, providerProps, delay = 1000, ...propsRest } = props;
32→  
33→  const [visible, setVisible] = React.useState(delay === 0);
34→  
35→  useEffectOnce(() => {
36→    if (delay === 0) { return; }
37→    globalThis.setTimeout(() => { setVisible(true); }, delay);
38→  });
39→  
40→  return (
41→    <ModalProvider
42→      active={visible}
43→      onActiveChange={setVisible}
44→      allowUserClose={false}
45→      unmountDelay={0} // No exit animation, once done we want the spinner away as fast as possible
46→      dialog={({ dialogProps }) =>
47→        <dialog {...dialogProps} inert aria-modal="true">
48→          <Spinner
49→            size="large"
50→            {...propsRest}
51→            className={cx(
52→              cl['bk-spinner-modal'],
53→              propsRest.className,
54→            )}
55→          />
56→        </dialog>
57→      }
58→      {...providerProps}
59→      ref={mergeRefs(modalRef, providerProps?.ref)}
60→    />
61→  );
62→};
